    if (disposed) return;
    if (!force && token !== modalMediaToken) return;
    disposed = true;
    clearRenderer();
    showImage();
    setGuidanceVisible(false);
    host.classList.remove("is-dragging-interactive");
    host.classList.remove("is-pinching-interactive");
    host.classList.remove("is-loading-interactive");
    host.classList.remove("is-interactive");
    host.style.removeProperty("--dish-interactive-scale");
    host.style.removeProperty("--dish-interactive-origin-x");
